mapper.select:
SELECT u.id, u.username, u.nickname, u.avatar, u.phone, u.email, u.gender, u.campus, u.intro, u.role, u.status, u.credit_score AS creditScore, u.last_login_time AS lastLoginTime, u.create_time AS createTime, (SELECT COUNT(*) FROM biz_product p WHERE p.user_id = u.id AND p.deleted = 0) AS productCount FROM sys_user u
AND ( u.username LIKE CONCAT('%', #{query.keyword}, '%') OR u.nickname LIKE CONCAT('%', #{query.keyword}, '%') OR u.phone LIKE CONCAT('%', #{query.keyword}, '%') )
AND u.role = #{query.role}
AND u.status = #{query.status}
ORDER BY u.create_time DESC, u.id DESC
